func (q *Queries) ListSubscriptions(ctx context.Context, arg ListSubscriptionsParams) ([]ListSubscriptionsRow, error) {
	rows, err := q.db.Query(ctx, listSubscriptions,
		arg.ID,
		arg.SocietyID,
		arg.PlanID,
		arg.Status,
		arg.PlanCode,
		arg.BillingCycle,
		arg.IsActiveOnly,
		arg.StartsAfter,
		arg.StartsBefore,
		arg.EndsAfter,
		arg.EndsBefore,
		arg.ExpiringBefore,
		arg.ExpiredOnly,
		arg.Search,
		arg.SearchMode,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListSubscriptionsRow{}
	for rows.Next() {
		var i ListSubscriptionsRow
		if err := rows.Scan(
			&i.ID,
			&i.SocietyID,
			&i.PlanID,
			&i.Status,
			&i.StartsAt,
			&i.EndsAt,
			&i.TrialEndsAt,
			&i.PlanName,
			&i.PlanCode,
			&i.PriceAmountPaise,
			&i.Currency,
			&i.BillingCycle,
			&i.MaxFlats,
			&i.MaxAdmins,
			&i.MaxStaff,
			&i.MaxResidents,
			&i.Features,
			&i.ActivatedAt,
			&i.ActivatedBy,
			&i.ExpiredAt,
			&i.CancelledAt,
			&i.CancelledBy,
			&i.CancellationReason,
			&i.Metadata,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SocietyName,
			&i.SocietyCode,
			&i.CurrentPlanName,
			&i.CurrentPlanCode,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

